"use client";
import {createContext,useContext,useCallback,useEffect,useMemo,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {ArrowDownToLine,ArrowRight,ArrowUpRight,Bell,CalendarDays,Check,CheckCheck,ChevronLeft,ChevronRight,Clock,Columns3,GripVertical,Inbox,List,Mail,Phone,Plus,RefreshCw,Search,Settings2,ShieldCheck,Sparkles,Target,UserRound,X} from 'lucide-react';
import {Badge,Button,ContentTabs,Empty,Field,Metric,Modal,PageHeading,Table} from './ui';
import {CRM_STAGES,type CrmAppointment,type CrmKind,type CrmLead,type CrmNotificationStatus,type CrmSettings,type CrmStage,type CrmState} from '@/lib/platform-crm/types';
import './crm.css';
import {ListPagination} from '@/components/fieldgrid/list-pagination';
import {useRouter,useSearchParams} from 'next/navigation';

const WEBSITE='https://www.fieldgrid.nl';
const kinds:Record<CrmKind,string>={appointment:'Afspraak',demo:'Demoaanvraag',trial:'30 dagen proberen'};
const stageName=(id:CrmStage)=>CRM_STAGES.find(s=>s.id===id)?.label||id;
const euros=(n:number)=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n||0);
const dayKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const plusDays=(day:string,n:number)=>{const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const dayLabel=(value:string,short=false)=>new Intl.DateTimeFormat('nl-NL',{timeZone:'Europe/Amsterdam',day:'numeric',month:short?'short':'long',...(!short?{year:'numeric'}:{})}).format(new Date(value.length===10?value+'T12:00:00Z':value));
const stamp=(value:string)=>new Intl.DateTimeFormat('nl-NL',{timeZone:'Europe/Amsterdam',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const dateInput=(value:string|null)=>value?dayKey(new Date(value)):'';
const dueISO=(value:string)=>value?new Date(value+'T10:00:00Z').toISOString():null;
const stageTone=(id:CrmStage)=>id==='won'?'success':id==='lost'?'neutral':id==='new'?'warning':'blue';
const mailLabels:Record<CrmNotificationStatus,string>={pending_config:'Instellen nodig',queued:'In wachtrij',sending:'Wordt aangeboden',accepted:'Aangeboden aan provider',failed:'Mislukt',demo:'Voorbeeld · geen mail',uncertain:'Uitkomst onzeker · niet opnieuw verzenden',deferred:'Uitgesteld',suppressed:'Geblokkeerd door beleid',cancelled:'Geannuleerd',expired:'Verlopen'};
const requestSort=(a:{createdAt:string},b:{createdAt:string})=>b.createdAt.localeCompare(a.createdAt);


async function api<T=CrmState>(path='',method='GET',body?:unknown,requestId?:string,signal?:AbortSignal):Promise<T>{
 const response=await fetch('/api/crm'+path,{method,credentials:'same-origin',headers:body!==undefined?{'Content-Type':'application/json',...(requestId?{'Idempotency-Key':requestId}:{})}:undefined,body:body!==undefined?JSON.stringify(body):undefined,cache:'no-store',signal});
 const result:unknown=await response.json().catch(()=>null);
 if(!result||typeof result!=='object'||Array.isArray(result))throw new Error('De server gaf geen geldig antwoord. Je invoer blijft behouden.');
 const r=result as Record<string,unknown>;
 if(!response.ok||r.ok===false)throw Object.assign(new Error(typeof r.error==='string'?r.error:'Opslaan is niet gelukt. Probeer het opnieuw.'),{status:response.status});return result as T;
}
type Mutate=(path:string,method:string,body:unknown,message?:string)=>Promise<boolean>;
const ReloadContext=createContext<()=>Promise<CrmState>>(()=>Promise.reject(new Error('Heropen het CRM om de nieuwste gegevens te laden.')));
const OwnerContext=createContext<CrmState['owners']>([]);
function ownerLabel(id:string,owners:CrmState['owners']){return owners.find(x=>x.id===id)?.name||'Niet toegewezen'}
function OwnerSelect({value,onChange}:{value:string;onChange:(id:string)=>void}){const owners=useContext(OwnerContext);return <select aria-label="Verantwoordelijke" value={value} onChange={e=>onChange(e.target.value)}><option value="">Niet toegewezen</option>{owners.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select>}
function ReloadLatest({busy,onLoad}:{busy:boolean;onLoad:(data:CrmState)=>void}){
 const reload=useContext(ReloadContext),[failure,setFailure]=useState('');
 return <><Button disabled={busy} onClick={async()=>{try{setFailure('');onLoad(await reload())}catch{setFailure('De nieuwste gegevens konden niet worden geladen. Je invoer blijft behouden.')}}}><RefreshCw size={14}/>Nieuwste gegevens laden</Button>{failure&&<Feedback error={failure}/>}</>;
}
function LeadSelect({data,value,onChange,disabled=false,required=false,emptyLabel}:{data:CrmState;value:string;onChange:(id:string)=>void;disabled?:boolean;required?:boolean;emptyLabel:string}){
 const [search,setSearch]=useState(''),[picked,setPicked]=useState<CrmLead|null>(null),[result,setResult]=useState<{search:string;leads:CrmLead[];total:number;error?:string}|null>(null);
 useEffect(()=>{const controller=new AbortController();const timer=setTimeout(()=>{void api('?'+new URLSearchParams({tab:'pipeline',search,pageSize:'100'}),'GET',undefined,undefined,controller.signal).then(d=>setResult({search,leads:d.leads,total:d.pagination.total})).catch(e=>{if(!controller.signal.aborted)setResult({search,leads:[],total:0,error:e.message})})},200);return()=>{clearTimeout(timer);controller.abort()}},[search]);
 const matches=result?.search===search?result:null;
 const selected=data.leads.find(l=>l.id===value)||(picked?.id===value?picked:null);
 const choices=[...(selected?[selected]:[]),...(matches?.leads||data.leads).filter(l=>l.id!==value)];
 return <>{!disabled&&<input type="search" aria-label="Zoek een lead om te koppelen" placeholder="Zoek bedrijf of contact…" value={search} onChange={e=>setSearch(e.target.value)}/>}<select aria-label={emptyLabel==='Algemene taak'?'Koppelen aan lead':'Lead'} disabled={disabled} required={required} value={value} onChange={e=>{setPicked(choices.find(l=>l.id===e.target.value)||null);onChange(e.target.value)}}><option value="">{emptyLabel}</option>{choices.map(l=><option key={l.id} value={l.id}>{l.company} · {l.name}</option>)}</select>{!disabled&&(!matches?<small role="status">Relaties zoeken…</small>:matches.error?<span role="alert">{matches.error}</span>:matches.total>100?<small>De eerste 100 relaties worden getoond. Verfijn je zoekopdracht.</small>:!matches.total?<small>Geen relaties gevonden. Voeg zo nodig eerst een lead toe via de pipeline.</small>:null)}</>;
}
function Feedback({error,notice}:{error?:string;notice?:string}){return error?<div className="crm-feedback error" role="alert"><ShieldCheck size={17}/><span>{error}</span></div>:notice?<div className="crm-feedback" role="status"><Check size={17}/><span>{notice}</span></div>:null}
function IButton({label,onClick,disabled=false,children}:{label:string;onClick:()=>void;disabled?:boolean;children:ReactNode}){return <button type="button" className="fg-action-icon" title={label} aria-label={label} disabled={disabled} onClick={onClick}>{children}</button>}
function SourceBadge({demo=false,kind}:{demo?:boolean;kind?:CrmKind}){return <span className={`crm-source ${demo?'demo':''}`}>{demo?'Voorbeeld':kind?kinds[kind]:'Handmatig'}</span>}
function StatusMail({status}:{status:CrmNotificationStatus}){return <Badge tone={status==='accepted'?'success':status==='failed'?'danger':status==='pending_config'?'warning':'neutral'}>{mailLabels[status]}</Badge>}

export function CRM(){
  const router=useRouter(),urlParams=useSearchParams();
  const [page,setPage]=useState(1),[pageSize,setPageSize]=useState(50),[detailPage,setDetailPage]=useState(1),[detailPageSize,setDetailPageSize]=useState(50);
  const [requestSearch,setRequestSearch]=useState(''),[requestKind,setRequestKind]=useState(''),[taskFilter,setTaskFilter]=useState('open'),[mailStatus,setMailStatus]=useState('all');
  const [agendaDate,setAgendaDate]=useState(dayKey),[agendaMode,setAgendaMode]=useState<'week'|'list'>('week'),[showCancelled,setShowCancelled]=useState(false);
  const controller=useRef<AbortController|null>(null);
  const mutationLock=useRef(false);
  const attempt=useRef<{signature:string;key:string}|null>(null);
  const [data,setData]=useState<CrmState|null>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
  const tab=['pipeline','requests','agenda','tasks','settings'].includes(urlParams.get('tab')||'')?urlParams.get('tab')!:'pipeline',leadId=urlParams.get('lead'),action=urlParams.get('action');
  const [query,setQuery]=useState(''),[kind,setKind]=useState(''),[owner,setOwner]=useState(''),[view,setView]=useState<'board'|'list'>('board'),[newLead,setNewLead]=useState(false),[newTask,setNewTask]=useState(false),[editingTask,setEditingTask]=useState<CrmState['tasks'][number]|null>(null),[appointment,setAppointment]=useState<CrmAppointment|null>(null),[scheduleLead,setScheduleLead]=useState<string|null>(null);
  const consumeAction=()=>{const p=new URLSearchParams(urlParams.toString());p.delete('action');router.replace(`/platform/crm${p.size?'?'+p:''}`,{scroll:false})};
  const mounted=useRef(true);
  const parameters=useMemo(()=>{
    const week=plusDays(agendaDate,-((new Date(agendaDate+'T12:00:00Z').getUTCDay()+6)%7));
    return new URLSearchParams({tab,search:tab==='requests'?requestSearch:tab==='pipeline'?query:'',kind:tab==='requests'?requestKind:tab==='pipeline'?kind:'',owner:tab==='pipeline'?owner:'',page:String(page),pageSize:String(pageSize),detailPage:String(detailPage),detailPageSize:String(detailPageSize),taskFilter,showCancelled:String(showCancelled),mailStatus,...(tab==='agenda'?{from:agendaMode==='week'?week:agendaDate,...(agendaMode==='week'?{until:plusDays(week,6)}:{})}:{}),...(leadId?{lead:leadId}:{})}).toString();
  },[tab,query,requestSearch,kind,requestKind,owner,page,pageSize,detailPage,detailPageSize,taskFilter,showCancelled,mailStatus,agendaDate,agendaMode,leadId]);
  const refresh=useCallback(async()=>{controller.current?.abort();const request=new AbortController();controller.current=request;try{const result=await api('?'+parameters,'GET',undefined,undefined,request.signal);if(mounted.current&&!request.signal.aborted)setData(result);return result}catch(e){if(e&&typeof e==='object'&&'status'in e&&e.status===403)setData(null);throw e}},[parameters]);
  useEffect(()=>{mounted.current=true;let active=true;void Promise.resolve().then(()=>refresh()).catch(e=>{if(active&&e.name!=='AbortError')setError(e.message)}).finally(()=>{if(active)setLoading(false)});const update=()=>{if(document.visibilityState==='visible')void refresh().catch(()=>{})};const timer=setInterval(update,30000);window.addEventListener('focus',update);return()=>{active=false;mounted.current=false;controller.current?.abort();clearInterval(timer);window.removeEventListener('focus',update)}},[refresh]);
  const navigate=(nextTab:string,nextLead:string|null=leadId)=>{setPage(1);const params=new URLSearchParams();if(nextTab!=='pipeline')params.set('tab',nextTab);if(nextLead)params.set('lead',nextLead);router.push(`/platform/crm${params.size?'?'+params:''}`,{scroll:false})};
  const openLead=(id:string)=>{setError('');setNotice('');setDetailPage(1);navigate(tab,id)};
  const mutate:Mutate=async(path,method,body,message='Wijziging opgeslagen.')=>{
    if(mutationLock.current)return false;
    const input={...(body as Record<string,unknown>)};
    const parts=path.split('/').filter(Boolean);
    if(method==='PATCH'||parts[0]==='notifications'){
      const record=parts[0]==='leads'?[...(data?.leads||[]),...(data?.detail?[data.detail.lead]:[])].find(x=>x.id===parts[1]):parts[0]==='tasks'?[...(data?.tasks||[]),...(data?.detail?.tasks||[])].find(x=>x.id===parts[1]):parts[0]==='appointments'?[...(data?.appointments||[]),...(data?.detail?.appointments||[])].find(x=>x.id===parts[1]):parts[0]==='notifications'?[...(data?.notifications||[]),...(data?.detail?.notifications||[])].find(x=>x.id===parts[1]):data?.settings;
      if(input.revision===undefined&&record)input.revision=record.revision;
    }
    const signature=JSON.stringify([path,method,input]);if(attempt.current?.signature!==signature)attempt.current={signature,key:crypto.randomUUID()};
    mutationLock.current=true;setBusy(true);setError('');setNotice('');
    try{const result=await api<{existing?:boolean}>(path,method,input,attempt.current.key);attempt.current=null;setNotice(result.existing?'Deze organisatie met dit e-mailadres staat al in de pipeline.':message);try{await refresh()}catch{setError('Opgeslagen. Het overzicht kon nog niet worden vernieuwd; laad de nieuwste gegevens voordat je verder wijzigt.')}return true}
    catch(e){if(e&&typeof e==='object'&&'status'in e&&e.status===403)setData(null);setError(e instanceof Error?e.message:'Opslaan is niet gelukt.');return false}finally{mutationLock.current=false;setBusy(false)}
  };
  const clearFeedback=()=>{setError('');setNotice('')};
  const chooseTab=(value:string)=>{clearFeedback();navigate(value,null)};
  if(loading)return <div className="crm-module sites-crm"><PageHeading eyebrow="PLATFORM / RELATIES" title="CRM & aanvragen"/><div className="crm-loading" role="status"><RefreshCw size={22}/> Je pipeline wordt geladen…</div></div>;
  if(!data)return <div className="crm-module sites-crm"><PageHeading eyebrow="PLATFORM / RELATIES" title="CRM & aanvragen"/><Feedback error={error}/><Button onClick={()=>{setLoading(true);refresh().then(()=>setError('')).catch(e=>setError(e.message)).finally(()=>setLoading(false))}}><RefreshCw size={16}/>Opnieuw laden</Button></div>;
  const detail=data.detail?.lead.id===leadId?data.detail:null;
  const lead=detail?.lead||data.leads.find(l=>l.id===leadId);
  const dialogData:CrmState=detail?{...data,...detail,leads:[detail.lead,...data.leads.filter(l=>l.id!==detail.lead.id)]}:data;
  const filtered=data.leads.filter(l=>data.pageLeadIds.includes(l.id)).sort(requestSort);
  const latestKind=(id:string)=>data.leads.find(l=>l.id===id)?.latestKind||data.requests.filter(r=>r.leadId===id).sort(requestSort)[0]?.kind;
  const filters=<div className="crm-filterbar"><label className="crm-search"><Search size={16}/><input type="search" aria-label="Zoek leads" placeholder="Zoek bedrijf, contact of branche…" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></label><select aria-label="Aanvraagtype" value={kind} onChange={e=>{setKind(e.target.value);setPage(1)}}><option value="">Alle aanvragen</option>{Object.entries(kinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select><select aria-label="Verantwoordelijke" value={owner} onChange={e=>{setOwner(e.target.value);setPage(1)}}><option value="">Alle eigenaren</option>{data.owners.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select>{(query||kind||owner)&&<IButton label="Filters wissen" onClick={()=>{setQuery('');setKind('');setOwner('')}}><X size={16}/></IButton>}</div>;
  return <ReloadContext.Provider value={async()=>{const result=await refresh();clearFeedback();return result}}><OwnerContext.Provider value={data.owners}><div className="crm-module sites-crm">
    <PageHeading eyebrow="PLATFORM / RELATIES" title="CRM & aanvragen" description="Van eerste interesse naar een nieuwe klant. Iedere aanvraag, afspraak en volgende stap op één plek." help="Websiteaanvragen worden centraal geregistreerd. Dezelfde organisatie en hetzelfde e-mailadres houden één leaddossier met alle aanvragen." actions={<><IButton label="Gegevens vernieuwen" disabled={busy} onClick={()=>{clearFeedback();refresh().then(()=>setNotice('Pipeline bijgewerkt.')).catch(e=>setError(e.message))}}><RefreshCw size={16}/></IButton><Button primary disabled={busy} onClick={()=>{clearFeedback();setNewLead(true)}}><Plus size={16}/>Nieuwe lead</Button></>}/>
    <div className="crm-metrics"><Metric label="Nieuwe aanvragen" value={data.counts.recentRequests} detail="afgelopen 7 dagen" icon={Inbox} onClick={()=>chooseTab('requests')}/><Metric label="Actieve leads" value={data.counts.active} detail={`${euros(data.counts.value)} potentiële maandwaarde`} icon={Target} onClick={()=>chooseTab('pipeline')}/><Metric label="Geplande afspraken" value={data.counts.appointments} detail={`${data.counts.requestedAppointments} nog bevestigen`} icon={CalendarDays} onClick={()=>chooseTab('agenda')}/><Metric label="Opvolging nodig" value={data.counts.tasks} detail={data.counts.overdueTasks?`${data.counts.overdueTasks} over de datum`:'open taken'} icon={CheckCheck} tone={data.counts.overdueTasks?'warning':'neutral'} onClick={()=>chooseTab('tasks')}/></div>
    <Feedback error={error} notice={notice}/>
    <ContentTabs label="CRM" value={tab} onValueChange={chooseTab} tabs={[
      {id:'pipeline',title:'Pipeline',content:<>
        <div className="crm-tab-heading"><div><h2>Je commerciële overzicht</h2><p>{data.pagination.total} leads · verplaats een kaart of wijzig de fase in het dossier.</p></div><div className="crm-view-toggle" aria-label="Pipelineweergave"><button className={view==='board'?'active':''} aria-pressed={view==='board'} onClick={()=>setView('board')}><Columns3 size={16}/>Bord</button><button className={view==='list'?'active':''} aria-pressed={view==='list'} onClick={()=>setView('list')}><List size={16}/>Lijst</button></div></div>
        {filters}
        {!data.leads.length?<div className="crm-welcome"><span><Target size={30}/></span><h3>Hier begint je volgende klantrelatie.</h3><p>Demoaanvragen, afspraken en aanvragen voor een proefperiode komen automatisch in deze pipeline. Voeg zelf een lead toe en leg de volgende stap vast.</p><div><Button primary onClick={()=>setNewLead(true)}><Plus size={15}/>Eerste lead toevoegen</Button></div><a href={WEBSITE+'/afspraak'} target="_blank" rel="noreferrer">Bekijk het afsprakenformulier <ArrowUpRight size={14}/></a></div>:view==='board'?<div className="crm-board" aria-label="Leadpipeline">{CRM_STAGES.map(stage=>{const rows=filtered.filter(l=>l.stage===stage.id);return <section className={`crm-column stage-${stage.id}`} key={stage.id} aria-label={stage.label} onDragOver={e=>{if(!busy){e.preventDefault();e.dataTransfer.dropEffect='move'}}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/fieldgrid-lead');const item=data.leads.find(l=>l.id===id);if(item&&item.stage!==stage.id&&!busy)void mutate('/leads/'+id,'PATCH',{stage:stage.id},`${item.company} verplaatst naar ${stage.label.toLowerCase()}.`)}}><header><span className="crm-stage-dot"/><h3>{stage.label}</h3><b>{data.selection[stage.id]?.count||0}</b></header><small className="crm-column-value">{euros(data.selection[stage.id]?.value||0)} / maand</small><div className="crm-column-cards">{rows.map(l=><button type="button" className="crm-lead-card" key={l.id} draggable={!busy} onDragStart={e=>{e.dataTransfer.setData('text/fieldgrid-lead',l.id);e.dataTransfer.effectAllowed='move'}} onClick={()=>openLead(l.id)}><div className="crm-card-top"><SourceBadge demo={l.isDemo} kind={latestKind(l.id)}/><GripVertical size={14}/></div><strong>{l.company}</strong><span className="crm-card-contact">{l.name}</span><span className="crm-card-sector">{l.sector||'Branche nog onbekend'}</span><footer><span><UserRound size={12}/>{ownerLabel(l.owner,data.owners)}</span>{l.value>0&&<b>{euros(l.value)}</b>}</footer>{l.nextActionAt&&<span className={`crm-card-due ${dateInput(l.nextActionAt)<dayKey()?'overdue':''}`}><Clock size={12}/>{dayLabel(l.nextActionAt,true)} · opvolgen</span>}</button>)}{!rows.length&&<div className="crm-column-empty">Geen leads in deze fase</div>}</div></section>})}</div>:<Table headers={['Organisatie / contact','Branche','Aanvraag','Fase','Eigenaar','Maandwaarde','Volgende actie']}>
          {filtered.map(l=><tr key={l.id}><td><button className="ed-record" onClick={()=>openLead(l.id)}>{l.company}</button><small>{l.name} · {l.email}</small></td><td>{l.sector||'—'}</td><td><SourceBadge demo={l.isDemo} kind={latestKind(l.id)}/></td><td><Badge tone={stageTone(l.stage)}>{stageName(l.stage)}</Badge></td><td>{ownerLabel(l.owner,data.owners)}</td><td>{euros(l.value)}</td><td>{l.nextActionAt?dayLabel(l.nextActionAt,true):'Nog inplannen'}</td></tr>)}
        </Table>}
        {!!data.leads.length&&!filtered.length&&<Empty title="Geen leads voor deze filters" text="Pas je zoekopdracht of selectie aan."/>}
        <div className="crm-bottom-note"><span><ShieldCheck size={14}/>Wijzigingen worden centraal opgeslagen.</span></div>
      </>},
      {id:'requests',title:`Aanvragen${data.counts.requests?' · '+data.counts.requests:''}`,content:<Requests data={data} filter={requestKind} setFilter={value=>{setRequestKind(value);setPage(1)}} search={requestSearch} setSearch={value=>{setRequestSearch(value);setPage(1)}} openLead={openLead} onAppointment={a=>{clearFeedback();setAppointment(a)}}/>},
      {id:'agenda',title:'Agenda',content:<Agenda data={data} date={agendaDate} setDate={value=>{setAgendaDate(value);setPage(1)}} mode={agendaMode} setMode={value=>{setAgendaMode(value);setPage(1)}} showCancelled={showCancelled} setShowCancelled={value=>{setShowCancelled(value);setPage(1)}} openLead={openLead} onAppointment={a=>{clearFeedback();setAppointment(a)}} onNew={()=>{clearFeedback();setScheduleLead('')}} onSettings={()=>chooseTab('settings')}/>},
      {id:'tasks',title:`Opvolging${data.counts.overdueTasks?' · '+data.counts.overdueTasks:''}`,content:<TaskList data={data} filter={taskFilter} setFilter={value=>{setTaskFilter(value);setPage(1)}} busy={busy} mutate={mutate} openLead={openLead} onNew={()=>{clearFeedback();setNewTask(true)}} onEdit={task=>{clearFeedback();setEditingTask(task)}}/>},
      {id:'settings',title:'Mail & beschikbaarheid',content:<Settings data={data} error={error} mailFilter={mailStatus} setMailFilter={value=>{setMailStatus(value);setPage(1)}} busy={busy} mutate={mutate} openLead={openLead}/>},
    ]}/>
    {leadId&&!detail&&<Modal title={lead?.company||'Leaddossier'} onClose={()=>navigate(tab,null)}><Feedback error={error}/>{!error&&<div role="status" className="crm-loading">Leaddossier laden…</div>}</Modal>}
    {lead&&detail&&<LeadDialog key={lead.id} lead={lead} data={dialogData} onDetailPage={setDetailPage} onDetailSize={size=>{setDetailPageSize(size);setDetailPage(1)}} busy={busy} error={error} notice={notice} mutate={mutate} onClose={()=>{clearFeedback();navigate(tab,null)}} onAppointment={a=>{clearFeedback();setAppointment(a)}} onSchedule={()=>{clearFeedback();setScheduleLead(lead.id)}}/>}
    <ListPagination preferenceKey="platform-crm" total={data.pagination.total} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={size=>{setPageSize(size);setPage(1)}} noun={tab==='pipeline'?'leads':tab==='requests'?'aanvragen':tab==='agenda'?'afspraken':tab==='tasks'?'taken':'meldingen'}/>
    {(newLead||action==='new-lead'||(action==='new-appointment'&&!Object.values(data.counts.stages).some(n=>n)))&&<NewLead busy={busy} error={error} mutate={mutate} onClose={()=>{setError('');setNewLead(false);consumeAction()}}/>}
    {(newTask||editingTask||action==='new-task')&&<NewTask data={data} task={editingTask} busy={busy} error={error} mutate={mutate} onClose={()=>{setError('');setNewTask(false);setEditingTask(null);consumeAction()}}/>}
    {(appointment||scheduleLead!==null||(action==='new-appointment'&&Object.values(data.counts.stages).some(n=>n)))&&<AppointmentDialog data={dialogData} appointment={appointment} initialLead={scheduleLead||''} busy={busy} error={error} mutate={mutate} onClose={()=>{setError('');setAppointment(null);setScheduleLead(null);consumeAction()}}/>}
  </div></OwnerContext.Provider></ReloadContext.Provider>
}

function Requests({data,filter,setFilter,search,setSearch,openLead,onAppointment}:{data:CrmState;filter:string;setFilter:(value:string)=>void;search:string;setSearch:(value:string)=>void;openLead:(id:string)=>void;onAppointment:(a:CrmAppointment)=>void}){
  const rows=[...data.requests].sort(requestSort);
  return <><div className="crm-tab-heading"><div><h2>Alles wat via de website binnenkomt</h2><p>Een aanvraag blijft bewaard, ook wanneer deze bij een bestaande lead hoort.</p></div><Badge>{data.pagination.total} aanvragen</Badge></div><div className="crm-filterbar"><label className="crm-search"><Search size={16}/><input type="search" aria-label="Zoek aanvragen" placeholder="Zoek een aanvraag…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Filter aanvraagtype" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">Alle typen</option>{Object.entries(kinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></div>
    {rows.length?<div className="crm-request-list">{rows.map(r=>{const l=data.leads.find(l=>l.id===r.leadId),a=data.appointments.find(a=>a.requestId===r.id),n=data.notifications.find(n=>n.requestId===r.id);return <article className="crm-request" key={r.id}><div className="crm-request-icon">{r.kind==='appointment'?<CalendarDays size={21}/>:r.kind==='trial'?<Sparkles size={21}/>:<Inbox size={21}/>}</div><div className="crm-request-body"><div className="crm-inline"><SourceBadge kind={r.kind} demo={r.isDemo}/><small>{stamp(r.createdAt)}</small></div><button className="ed-record" onClick={()=>openLead(r.leadId)}>{r.company||l?.company||'Leaddossier'} <ArrowUpRight size={13}/></button><p>{r.name||l?.name} · {r.email||l?.email}</p>{r.goal&&<strong className="crm-small-title">{r.goal}</strong>}{r.message&&<p className="crm-request-message">{r.message}</p>}<div className="crm-inline">{a&&<button className="crm-inline-button" onClick={()=>onAppointment(a)}><CalendarDays size={14}/>{dayLabel(a.date,true)} · {a.time} · {a.status==='cancelled'?'Geannuleerd':a.status==='confirmed'?'Bevestigd':'Te bevestigen'}</button>}{n&&<StatusMail status={n.status}/>}</div></div><IButton label={`Open aanvraag van ${l?.company||'lead'}`} onClick={()=>openLead(r.leadId)}><ChevronRight size={17}/></IButton></article>})}</div>:<Empty title="Nog geen aanvragen" text="Een afspraak, demoaanvraag of proefaanvraag via de website verschijnt hier automatisch."/>}
  </>
}

function Agenda({data,openLead,onAppointment,onNew,onSettings,date,setDate,mode,setMode,showCancelled,setShowCancelled}:{data:CrmState;date:string;setDate:(value:string)=>void;mode:"week"|"list";setMode:(value:"week"|"list")=>void;showCancelled:boolean;setShowCancelled:(value:boolean)=>void;openLead:(id:string)=>void;onAppointment:(a:CrmAppointment)=>void;onNew:()=>void;onSettings:()=>void}){
  const weekStart=plusDays(date,-((new Date(date+'T12:00:00Z').getUTCDay()+6)%7));
  const days=Array.from({length:7},(_,i)=>plusDays(weekStart,i));
  const appointments=data.appointments.filter(a=>(showCancelled||a.status!=='cancelled')&&(mode==='week'?days.includes(a.date):a.date>=date)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
  return <><div className="crm-tab-heading"><div><h2>Ruimte voor goede gesprekken</h2><p>Telefonische afspraken van 30 minuten · tijdzone Amsterdam.</p></div><Button primary onClick={onNew} disabled={!Object.values(data.counts.stages).some(n=>n)}><Plus size={15}/>Afspraak plannen</Button></div><div className="crm-calendar-toolbar"><div className="ed-date-control"><IButton label="Vorige week" onClick={()=>setDate(plusDays(date,-7))}><ChevronLeft size={15}/></IButton><input type="date" aria-label="Datum agenda" value={date} onChange={e=>e.target.value&&setDate(e.target.value)}/><IButton label="Volgende week" onClick={()=>setDate(plusDays(date,7))}><ChevronRight size={15}/></IButton><Button onClick={()=>setDate(dayKey())}>Vandaag</Button></div><div className="crm-view-toggle"><button className={mode==='week'?'active':''} aria-pressed={mode==='week'} onClick={()=>setMode('week')}><CalendarDays size={15}/>Week</button><button className={mode==='list'?'active':''} aria-pressed={mode==='list'} onClick={()=>setMode('list')}><List size={15}/>Lijst</button></div></div>
    <div className="crm-calendar-summary"><span><i/>Beschikbaar: {data.settings.startTime}–{data.settings.endTime} · {data.settings.bufferMinutes} min buffer</span><button className="ed-link" onClick={onSettings}>Beschikbaarheid beheren <Settings2 size={13}/></button></div>
    {mode==='week'?<div className="crm-week-scroll"><div className="crm-week">{days.map(day=>{const weekDay=new Date(day+'T12:00:00Z').getUTCDay();const open=data.settings.weekdays.includes(weekDay)&&!data.settings.blockedDates.includes(day);const items=appointments.filter(a=>a.date===day);return <section className={`crm-day ${day===dayKey()?'today':''} ${!open?'closed':''}`} key={day}><header><span>{new Intl.DateTimeFormat('nl-NL',{weekday:'short'}).format(new Date(day+'T12:00:00Z'))}</span><strong>{new Date(day+'T12:00:00Z').getUTCDate()}</strong><small>{open?'Beschikbaar':'Gesloten'}</small></header><div>{items.map(a=>{const l=data.leads.find(l=>l.id===a.leadId);return <button key={a.id} className={`crm-event ${a.status}`} onClick={()=>onAppointment(a)}><span>{a.time}–{a.endTime}</span><strong>{l?.company||'Afspraak'}</strong><small><Phone size={11}/>{l?.name}</small><em>{a.status==='confirmed'?'Bevestigd':a.status==='cancelled'?'Geannuleerd':'Te bevestigen'}</em>{a.isDemo&&<i>Voorbeeld</i>}</button>})}{!items.length&&<span className="crm-day-empty">{open?'Geen afspraken':'—'}</span>}</div></section>})}</div></div>:appointments.length?<Table headers={['Datum & tijd','Organisatie','Contact','Status','Acties']}>{appointments.map(a=>{const l=data.leads.find(l=>l.id===a.leadId);return <tr key={a.id}><td><strong>{dayLabel(a.date,true)}</strong><small>{a.time}–{a.endTime}</small></td><td><button className="ed-record" onClick={()=>openLead(a.leadId)}>{l?.company}</button>{a.isDemo&&<small>Voorbeeld</small>}</td><td>{l?.name}<small>{l?.phone||'Telefoon nog onbekend'}</small></td><td><Badge tone={a.status==='confirmed'?'success':a.status==='requested'?'warning':'neutral'}>{a.status==='confirmed'?'Bevestigd':a.status==='requested'?'Te bevestigen':'Geannuleerd'}</Badge></td><td><Button onClick={()=>onAppointment(a)}>Beheren <ChevronRight size={14}/></Button></td></tr>})}</Table>:<Empty title="Geen afspraken vanaf deze datum" text="Kies een eerdere datum of plan een afspraak vanuit een leaddossier."/>}
    <div className="crm-bottom-note"><label className="crm-check"><input type="checkbox" checked={showCancelled} onChange={e=>setShowCancelled(e.target.checked)}/>Geannuleerde afspraken tonen</label><span>Afspraken blijven gereserveerd totdat je ze annuleert.</span></div>
  </>
}

function TaskList({data,busy,mutate,openLead,onNew,onEdit,filter,setFilter}:{data:CrmState;filter:string;setFilter:(value:string)=>void;busy:boolean;mutate:Mutate;openLead:(id:string)=>void;onNew:()=>void;onEdit:(task:CrmState['tasks'][number])=>void}){
  const rows=data.tasks.filter(t=>filter==='all'||(filter==='done'?t.completed:filter==='overdue'?!t.completed&&t.dueAt&&dateInput(t.dueAt)<dayKey():!t.completed)).sort((a,b)=>(a.dueAt||'9999').localeCompare(b.dueAt||'9999'));
  return <><div className="crm-tab-heading"><div><h2>Een duidelijke volgende stap</h2><p>Bel terug, bereid een demo voor of volg een voorstel op.</p></div><Button primary onClick={onNew}><Plus size={15}/>Nieuwe taak</Button></div><div className="crm-pills" aria-label="Taakfilter">{[['open','Open taken'],['overdue','Over de datum'],['done','Afgerond'],['all','Alles']].map(([id,label])=><button key={id} className={filter===id?'active':''} aria-pressed={filter===id} onClick={()=>setFilter(id)}>{label}</button>)}</div><div className="crm-task-list">{rows.map(t=>{const l=data.leads.find(l=>l.id===t.leadId);const late=!t.completed&&t.dueAt&&dateInput(t.dueAt)<dayKey();return <article className={`crm-task ${t.completed?'done':''}`} key={t.id}><button className="crm-task-check" aria-label={`${t.title}: ${t.completed?'heropenen':'afronden'}`} aria-pressed={t.completed} disabled={busy} onClick={()=>mutate('/tasks/'+t.id,'PATCH',{completed:!t.completed},t.completed?'Taak heropend.':'Taak afgerond.')}>{t.completed&&<Check size={15}/>}</button><div><button className="ed-record crm-task-title" onClick={()=>onEdit(t)}>{t.title}</button><div className="crm-inline">{l&&<button className="ed-link" onClick={()=>openLead(l.id)}>{l.company}<ArrowUpRight size={12}/></button>}<span>{ownerLabel(t.owner,data.owners)}</span>{t.isDemo&&<SourceBadge demo/>}</div></div><span className={`crm-task-date ${late?'overdue':''}`}><Clock size={13}/>{t.dueAt?dayLabel(t.dueAt,true):'Geen deadline'}</span></article>})}{!rows.length&&<Empty title={filter==='done'?'Nog geen afgeronde taken':'Je bent bij voor deze selectie'} text={filter==='open'?'Nieuwe websiteaanvragen krijgen automatisch een opvolgtaak. Je kunt ook zelf een taak toevoegen.':'Kies een andere selectie om meer taken te bekijken.'}/>}</div></>
}

function LeadDialog({lead,data,busy,error,notice,mutate,onClose,onAppointment,onSchedule,onDetailPage,onDetailSize}:{lead:CrmLead;data:CrmState;onDetailPage:(page:number)=>void;onDetailSize:(size:number)=>void;busy:boolean;error:string;notice:string;mutate:Mutate;onClose:()=>void;onAppointment:(a:CrmAppointment)=>void;onSchedule:()=>void}){
  const [draft,setDraft]=useState({stage:lead.stage,owner:lead.owner,value:lead.value,nextAction:dateInput(lead.nextActionAt),revision:lead.revision}),[note,setNote]=useState(''),[task,setTask]=useState(''),[taskDue,setTaskDue]=useState(dayKey()),[tab,setTab]=useState('overview');

  const requests=data.requests.filter(r=>r.leadId===lead.id).sort(requestSort),activities=data.activities.filter(a=>a.leadId===lead.id).sort(requestSort),appointments=data.appointments.filter(a=>a.leadId===lead.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),tasks=data.tasks.filter(t=>t.leadId===lead.id);
  return <Modal title={lead.company} subtitle={`CRM / ${lead.isDemo?'VOORBEELDLEAD':'LEADDOSSIER'}`} wide onClose={onClose} footer={<><Button onClick={onClose}>Sluiten</Button><Button primary disabled={busy} onClick={async()=>{if(await mutate('/leads/'+lead.id,'PATCH',{stage:draft.stage,owner:draft.owner,value:Number(draft.value)||0,nextActionAt:dueISO(draft.nextAction),revision:draft.revision},'Leaddossier opgeslagen.'))setDraft({...draft,revision:draft.revision+1})}}><Check size={15}/>{busy?'Opslaan…':'Dossier opslaan'}</Button></>}>
    <div className="crm-lead-hero"><span className="crm-company-mark">{lead.company.split(' ').slice(0,2).map(s=>s[0]).join('')}</span><div><strong>{lead.name}</strong><span>{lead.sector||'Branche onbekend'}{lead.team?' · '+lead.team+(/medewerkers?/.test(lead.team)?'':' medewerkers'):''}</span><small>Sinds {dayLabel(lead.createdAt,true)} · {['manual','Handmatig'].includes(lead.source)?'Handmatig toegevoegd':'Websiteaanvraag'}</small></div><Badge tone={stageTone(lead.stage)}>{stageName(lead.stage)}</Badge></div>
    <div className="crm-contact-actions"><a className="secondary-button" href={'mailto:'+lead.email}><Mail size={15}/>{lead.email}</a>{lead.phone&&<a className="secondary-button" href={'tel:'+lead.phone.replace(/[^+\d]/g,'')}><Phone size={15}/>{lead.phone}</a>}<Button onClick={onSchedule}><CalendarDays size={15}/>Afspraak plannen</Button></div>
    <Feedback error={error} notice={notice}/>{error&&<ReloadLatest busy={busy} onLoad={fresh=>{const l=fresh.detail?.lead;if(l)setDraft({stage:l.stage,owner:l.owner,value:l.value,nextAction:dateInput(l.nextActionAt),revision:l.revision})}}/>}
    <ContentTabs label="Leaddossier" value={tab} onValueChange={value=>{setTab(value);onDetailPage(1)}} tabs={[
      {id:'overview',title:'Overzicht',content:<><div className="crm-form-grid"><Field label="Fase"><select value={draft.stage} onChange={e=>setDraft({...draft,stage:e.target.value as CrmStage})}>{CRM_STAGES.map(s=><option value={s.id} key={s.id}>{s.label}</option>)}</select></Field><Field label="Verantwoordelijke"><OwnerSelect value={draft.owner} onChange={owner=>setDraft({...draft,owner})}/></Field><Field label="Potentiële maandwaarde (€)"><input type="number" min="0" step="1" value={draft.value} onChange={e=>setDraft({...draft,value:Number(e.target.value)})}/></Field><Field label="Volgende contactmoment"><input type="date" value={draft.nextAction} onChange={e=>setDraft({...draft,nextAction:e.target.value})}/></Field></div><div className="crm-detail-section"><h3><CalendarDays size={16}/>Afspraken</h3>{appointments.length?appointments.map(a=><button key={a.id} className="crm-appointment-line" onClick={()=>onAppointment(a)}><span className="crm-mini-date"><strong>{new Date(a.date+'T12:00:00Z').getUTCDate()}</strong><small>{new Intl.DateTimeFormat('nl-NL',{month:'short'}).format(new Date(a.date+'T12:00:00Z'))}</small></span><span><strong>Telefonische kennismaking</strong><small>{a.time}–{a.endTime} · {a.status==='confirmed'?'Bevestigd':a.status==='cancelled'?'Geannuleerd':'Bevestiging nodig'}</small></span><ChevronRight size={15}/></button>):<p className="crm-muted">Er is nog geen afspraak gepland.</p>}</div></>},
      {id:'requests',title:`Aanvragen · ${(data.detail?.totals.requests??requests.length)}`,content:<div className="crm-history">{requests.map(r=><article key={r.id}><span className="crm-timeline-dot"/><div><div className="crm-inline"><strong>{kinds[r.kind]}</strong><small>{stamp(r.createdAt)}</small></div>{r.goal&&<p>{r.goal}</p>}{r.message&&<p className="crm-prewrap">{r.message}</p>}{r.date&&<small>{dayLabel(r.date,true)} · {r.time}</small>}</div></article>)}{!requests.length&&<Empty title="Handmatig toegevoegd" text="Nieuwe websiteaanvragen van dit bedrijf met hetzelfde e-mailadres worden aan dit dossier gekoppeld."/>}</div>},
      {id:'activity',title:'Notities & tijdlijn',content:<><Field label="Interne notitie"><textarea rows={3} value={note} onChange={e=>setNote(e.target.value)} placeholder="Wat is besproken? Wat is belangrijk voor de volgende stap?"/></Field><div><Button disabled={busy||!note.trim()} primary onClick={async()=>{if(await mutate('/leads/'+lead.id+'/activity','POST',{body:note.trim()},'Notitie toegevoegd.'))setNote('')}}><Plus size={14}/>Notitie toevoegen</Button></div><div className="crm-history">{activities.map(a=><article key={a.id}><span className="crm-timeline-dot"/><div><small>{stamp(a.createdAt)}</small><p className="crm-prewrap">{a.body}</p></div></article>)}{!activities.length&&<p className="crm-muted">De eerste activiteit verschijnt hier zodra je de lead bijwerkt.</p>}</div></>},
      {id:'tasks',title:`Taken · ${(data.detail?.totals.openTasks??tasks.filter(t=>!t.completed).length)}`,content:<><div className="crm-form-grid"><Field label="Nieuwe opvolgtaak"><input value={task} onChange={e=>setTask(e.target.value)} placeholder="Bijvoorbeeld terugbellen"/></Field><Field label="Uiterlijk op"><input type="date" value={taskDue} onChange={e=>setTaskDue(e.target.value)}/></Field></div><div><Button disabled={busy||!task.trim()} primary onClick={async()=>{if(await mutate('/tasks','POST',{leadId:lead.id,title:task,dueAt:dueISO(taskDue),owner:draft.owner},'Opvolgtaak toegevoegd.'))setTask('')}}><Plus size={14}/>Taak toevoegen</Button></div><div className="crm-task-list">{tasks.map(t=><article className={`crm-task ${t.completed?'done':''}`} key={t.id}><button className="crm-task-check" disabled={busy} aria-label={`${t.title} ${t.completed?'heropenen':'afronden'}`} aria-pressed={t.completed} onClick={()=>mutate('/tasks/'+t.id,'PATCH',{completed:!t.completed},t.completed?'Taak heropend.':'Taak afgerond.')}>{t.completed&&<Check size={15}/>}</button><div><strong>{t.title}</strong><small>{ownerLabel(t.owner,data.owners)}</small></div><span className="crm-task-date">{t.dueAt?dayLabel(t.dueAt,true):'Geen datum'}</span></article>)}</div></>},
    ]}/>
    {data.detail&&(tab!=='overview'||data.detail.totals.appointments>data.detail.pageSize)&&<ListPagination preferenceKey="crm-dossier" total={data.detail.totals[tab==='requests'?'requests':tab==='activity'?'activities':tab==='tasks'?'tasks':'appointments']} page={data.detail.page} pageSize={data.detail.pageSize} onPageChange={onDetailPage} onPageSizeChange={onDetailSize} noun={tab==='requests'?'aanvragen':tab==='activity'?'registraties':tab==='tasks'?'taken':'afspraken'}/>}
  </Modal>
}

function NewLead({busy,error,mutate,onClose}:{busy:boolean;error:string;mutate:Mutate;onClose:()=>void}){
  const [draft,setDraft]=useState({company:'',name:'',email:'',phone:'',sector:'',owner:'',stage:'new'});
  const save=async(e:FormEvent)=>{e.preventDefault();if(await mutate('/leads','POST',draft,'Lead toegevoegd aan de pipeline.'))onClose()};
  return <Modal title="Nieuwe lead" subtitle="CRM / RELATIE TOEVOEGEN" onClose={onClose} footer={<><Button disabled={busy} onClick={onClose}>Annuleren</Button><Button form="crm-new-lead" type="submit" primary disabled={busy}>{busy?'Opslaan…':'Lead toevoegen'}<ArrowRight size={15}/></Button></>}><Feedback error={error}/><form id="crm-new-lead" onSubmit={save}><div className="crm-form-grid"><Field label="Bedrijfsnaam *"><input required value={draft.company} onChange={e=>setDraft({...draft,company:e.target.value})}/></Field><Field label="Contactpersoon *"><input required value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></Field><Field label="E-mailadres *"><input required type="email" value={draft.email} onChange={e=>setDraft({...draft,email:e.target.value})}/></Field><Field label="Telefoonnummer"><input type="tel" value={draft.phone} onChange={e=>setDraft({...draft,phone:e.target.value})}/></Field><Field label="Branche"><select value={draft.sector} onChange={e=>setDraft({...draft,sector:e.target.value})}><option value="">Selecteer een branche</option>{['Schoonmaak','Glasbewassing','Facilitair','Groenonderhoud','Vastgoedservice','Beveiliging','Evenementen','Anders'].map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Verantwoordelijke"><OwnerSelect value={draft.owner} onChange={owner=>setDraft({...draft,owner})}/></Field></div><p className="crm-muted">Je voegt een relatie handmatig toe. Er wordt geen e-mail verstuurd.</p></form></Modal>
}

function NewTask({data,task,busy,error,mutate,onClose}:{data:CrmState;task?:CrmState['tasks'][number]|null;busy:boolean;error:string;mutate:Mutate;onClose:()=>void}){
  const [draft,setDraft]=useState({title:task?.title||'',leadId:task?.leadId||'',due:task?dateInput(task.dueAt):dayKey(),owner:task?.owner||'',revision:task?.revision});
  return <Modal title={task?'Opvolgtaak bewerken':'Nieuwe opvolgtaak'} subtitle="CRM / OPVOLGING" onClose={onClose} footer={<><Button disabled={busy} onClick={onClose}>Annuleren</Button><Button type="submit" form="crm-new-task" disabled={busy} primary>{task?'Wijzigingen opslaan':'Taak toevoegen'}</Button></>}><Feedback error={error}/>{error&&task&&<ReloadLatest busy={busy} onLoad={fresh=>{const current=fresh.tasks.find(t=>t.id===task.id);if(!current)throw new Error();setDraft({title:current.title,leadId:current.leadId||'',due:dateInput(current.dueAt),owner:current.owner,revision:current.revision})}}/>}<form id="crm-new-task" onSubmit={async e=>{e.preventDefault();if(await mutate(task?'/tasks/'+task.id:'/tasks',task?'PATCH':'POST',{title:draft.title,...(!task?{leadId:draft.leadId||null}:{revision:draft.revision}),dueAt:dueISO(draft.due),owner:draft.owner},task?'Opvolgtaak bijgewerkt.':'Opvolgtaak toegevoegd.'))onClose()}}><Field label="Wat moet er gebeuren? *"><input required value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} placeholder="Bijvoorbeeld voorstel nabellen"/></Field><Field group label="Koppelen aan lead"><LeadSelect data={data} value={draft.leadId} onChange={leadId=>setDraft({...draft,leadId})} disabled={!!task} emptyLabel="Algemene taak"/></Field><div className="crm-form-grid"><Field label="Uiterlijk op"><input type="date" value={draft.due} onChange={e=>setDraft({...draft,due:e.target.value})}/></Field><Field label="Verantwoordelijke"><OwnerSelect value={draft.owner} onChange={owner=>setDraft({...draft,owner})}/></Field></div></form></Modal>
}

function AppointmentDialog({data,appointment,initialLead,busy,error,mutate,onClose}:{data:CrmState;appointment:CrmAppointment|null;initialLead:string;busy:boolean;error:string;mutate:Mutate;onClose:()=>void}){
  const [leadId,setLeadId]=useState(appointment?.leadId||initialLead),[date,setDate]=useState(appointment?.date||plusDays(dayKey(),1)),[time,setTime]=useState(appointment?.time||''),[slots,setSlots]=useState<string[]>([]),[loading,setLoading]=useState(false),[slotError,setSlotError]=useState(''),[reschedule,setReschedule]=useState(!appointment),[revision,setRevision]=useState(appointment?.revision),[slotVersion,setSlotVersion]=useState(0),[cancelConfirm,setCancelConfirm]=useState(false);
  const detail=data.detail?.lead.id===leadId?data.detail:null;
  const lead=detail?.lead||data.leads.find(l=>l.id===leadId);
  const latest=appointment?data.appointments.find(a=>a.id===appointment.id)||appointment:null;
  useEffect(()=>{if(!reschedule)return;let active=true;const frame=requestAnimationFrame(()=>{setLoading(true);setSlotError('');setSlots([]);setTime('');api<{slots:string[]}>('/availability?date='+date).then(result=>{if(active)setSlots(result.slots||[])}).catch(e=>{if(active)setSlotError(e.message)}).finally(()=>{if(active)setLoading(false)});});return()=>{active=false;cancelAnimationFrame(frame)}},[date,reschedule,slotVersion]);
  const save=async(e:FormEvent)=>{e.preventDefault();if(!time||!leadId)return;const done=latest?await mutate('/appointments/'+latest.id,'PATCH',{action:'reschedule',date,time,revision},'Afspraak verplaatst. Het nieuwe tijdstip is gereserveerd.'):await mutate('/appointments','POST',{leadId,date,time},'Afspraak toegevoegd aan de agenda.');if(done)onClose()};
  return <Modal title={latest?'Afspraak beheren':'Afspraak plannen'} subtitle="TELEFONISCHE KENNISMAKING / 30 MINUTEN" onClose={onClose} footer={<><Button disabled={busy} onClick={onClose}>Sluiten</Button>{reschedule&&<Button primary disabled={busy||!time||!leadId||!!slotError} form="crm-appointment" type="submit">{latest?'Verplaats afspraak':'Plan afspraak'}<CalendarDays size={15}/></Button>}</>}>
    <Feedback error={error}/>{(error||slotError)&&<Button disabled={busy} onClick={()=>{setSlotVersion(v=>v+1)}}><RefreshCw size={14}/>Vrije tijden opnieuw laden</Button>}
    {latest&&!reschedule?<><div className="crm-appointment-summary"><span><Phone size={25}/></span><h3>{lead?.company}</h3><p>{lead?.name} · {lead?.phone||'Telefoonnummer niet bekend'}</p><strong>{dayLabel(latest.date)}</strong><b>{latest.time}–{latest.endTime}</b><Badge tone={latest.status==='confirmed'?'success':latest.status==='cancelled'?'neutral':'warning'}>{latest.status==='confirmed'?'Bevestigd':latest.status==='cancelled'?'Geannuleerd':'Nog bevestigen'}</Badge></div><div className="crm-appointment-actions">{latest.status==='requested'&&<Button primary disabled={busy} onClick={async()=>{if(await mutate('/appointments/'+latest.id,'PATCH',{action:'confirm',revision:latest.revision},'Afspraak bevestigd in de agenda.'))onClose()}}><Check size={15}/>Afspraak bevestigen</Button>}{latest.status!=='cancelled'&&<><Button onClick={()=>{setRevision(latest.revision);setReschedule(true)}}><CalendarDays size={15}/>Verplaatsen</Button><a className="secondary-button" href={'/api/crm/appointments/'+latest.id+'/ics'} download><ArrowDownToLine size={15}/>Toevoegen aan agenda</a><Button disabled={busy} onClick={()=>setCancelConfirm(true)}><X size={15}/>Annuleren</Button></>}</div>{cancelConfirm&&<div className="crm-cancel-box"><strong>Deze afspraak annuleren?</strong><p>Het tijdslot wordt weer beschikbaar. Het leaddossier en de aanvraag blijven bewaard.</p><div><Button onClick={()=>setCancelConfirm(false)}>Behouden</Button><Button disabled={busy} onClick={async()=>{if(await mutate('/appointments/'+latest.id,'PATCH',{action:'cancel',revision:latest.revision},'Afspraak geannuleerd. Het tijdslot is weer vrij.'))onClose()}}>Ja, annuleren</Button></div></div>}<p className="crm-muted">De agenda-download werkt met Outlook, Google Calendar en Apple Agenda. Een download synchroniseert latere wijzigingen niet automatisch.</p></>:<form id="crm-appointment" onSubmit={save}><Field group label="Lead *"><LeadSelect data={data} value={leadId} onChange={setLeadId} required disabled={!!latest} emptyLabel="Kies een relatie"/></Field><Field label="Datum *"><input required type="date" min={dayKey()} max={plusDays(dayKey(),data.settings.horizonDays)} value={date} onChange={e=>setDate(e.target.value)}/></Field><div className="crm-slot-label">Beschikbare begintijden <span>Amsterdam · 30 minuten</span></div>{loading?<p className="crm-muted" role="status">Vrije tijden laden…</p>:slotError?<Feedback error={slotError}/>:slots.length?<div className="crm-slots">{slots.map(slot=><button key={slot} type="button" className={time===slot?'active':''} aria-pressed={time===slot} onClick={()=>setTime(slot)}>{slot}</button>)}</div>:<div className="crm-empty-slots">Geen vrije tijden op deze dag. Kies een andere datum of pas de beschikbaarheid aan.</div>}<p className="crm-muted">Het gekozen tijdslot wordt gecontroleerd en gereserveerd bij het opslaan.</p>{latest&&<button className="ed-link" type="button" onClick={()=>setReschedule(false)}>Terug naar afspraak</button>}</form>}
  </Modal>
}

function Settings({data,busy,error,mutate,openLead,mailFilter,setMailFilter}:{data:CrmState;error:string;mailFilter:string;setMailFilter:(value:string)=>void;busy:boolean;mutate:Mutate;openLead:(id:string)=>void}){
  const [settings,setSettings]=useState<CrmSettings>(data.settings),[block,setBlock]=useState(''),[notificationId,setNotificationId]=useState<string|null>(null);
  const save=async(e:FormEvent)=>{e.preventDefault();if(await mutate('/settings','PATCH',settings,'Beschikbaarheid en meldingsvoorkeur opgeslagen.'))setSettings({...settings,revision:settings.revision+1})};
  const outbox=[...data.notifications].sort(requestSort);
  return <>{error&&<ReloadLatest busy={busy} onLoad={fresh=>setSettings(fresh.settings)}/>}<div className="crm-tab-heading"><div><h2>Jouw agenda. Jouw opvolging.</h2><p>Bepaal wanneer bezoekers kunnen afspreken. Meldingen volgen je bestaande platformaccount.</p></div></div>
    <form id="crm-settings" onSubmit={save} className="crm-settings-grid">
      <section className="crm-settings-card"><div className="crm-settings-title"><CalendarDays size={20}/><div><h3>Beschikbaarheid</h3><p>De website gebruikt deze vrije momenten.</p></div></div><div className="crm-slot-label">Werkdagen</div><div className="crm-weekdays">{[[1,'Ma'],[2,'Di'],[3,'Wo'],[4,'Do'],[5,'Vr'],[6,'Za'],[0,'Zo']].map(([id,label])=><button type="button" key={id} className={settings.weekdays.includes(Number(id))?'active':''} aria-pressed={settings.weekdays.includes(Number(id))} onClick={()=>setSettings({...settings,weekdays:settings.weekdays.includes(Number(id))?settings.weekdays.filter(d=>d!==Number(id)):[...settings.weekdays,Number(id)]})}>{label}</button>)}</div><div className="crm-form-grid"><Field label="Vanaf"><input type="time" step="900" required value={settings.startTime} onChange={e=>setSettings({...settings,startTime:e.target.value})}/></Field><Field label="Tot"><input type="time" step="900" required value={settings.endTime} onChange={e=>setSettings({...settings,endTime:e.target.value})}/></Field><Field label="Buffer tussen gesprekken"><select value={settings.bufferMinutes} onChange={e=>setSettings({...settings,bufferMinutes:Number(e.target.value)})}>{[0,15,30,45,60].map(n=><option key={n} value={n}>{n} minuten</option>)}</select></Field><Field label="Minimaal vooraf boeken"><select value={settings.leadTimeHours} onChange={e=>setSettings({...settings,leadTimeHours:Number(e.target.value)})}>{[0,1,2,4,12,24,48,72].map(n=><option key={n} value={n}>{n} uur</option>)}</select></Field><Field label="Vooruit boeken"><select value={settings.horizonDays} onChange={e=>setSettings({...settings,horizonDays:Number(e.target.value)})}>{[7,14,30,60].map(n=><option key={n} value={n}>{n} dagen</option>)}</select></Field><Field label="Gespreksduur"><input readOnly value="30 minuten · telefonisch"/></Field></div><div className="crm-block-date"><Field label="Dag blokkeren (vakantie of afwezig)"><input type="date" min={dayKey()} value={block} onChange={e=>setBlock(e.target.value)}/></Field><IButton label="Blokdag toevoegen" disabled={!block||settings.blockedDates.includes(block)} onClick={()=>{setSettings({...settings,blockedDates:[...settings.blockedDates,block].sort()});setBlock('')}}><Plus size={18}/></IButton></div><div className="crm-blocked-days">{settings.blockedDates.map(day=><span key={day}>{dayLabel(day,true)}<button type="button" aria-label={`Blokkade ${dayLabel(day)} verwijderen`} onClick={()=>setSettings({...settings,blockedDates:settings.blockedDates.filter(d=>d!==day)})}><X size={13}/></button></span>)}</div><p className="crm-muted">Een blokdag voorkomt nieuwe reserveringen. Bestaande afspraken blijven staan totdat je ze verplaatst of annuleert.</p></section>
      <section className="crm-settings-card"><div className="crm-settings-title"><Bell size={20}/><div><h3>Een melding bij iedere aanvraag</h3><p>Geen gemiste interesse van een potentiële klant.</p></div></div><label className="crm-switch-line"><span><strong>E-mailmeldingen</strong><small>Een melding naar jou als platformbeheerder.</small></span><input type="checkbox" checked={settings.emailEnabled} onChange={e=>setSettings({...settings,emailEnabled:e.target.checked})}/></label><div className="crm-global-recipient"><span>Ontvanger</span><strong>{data.notificationContext.recipientName||'Platformbeheerder'}</strong><p>{data.notificationContext.recipientEmail||'Accountadres van de bestaande platformbeheerder'}</p><small>Automatisch gekoppeld aan het beheeraccount.</small></div><div className={`crm-provider-status ${data.mailConfigured?'ready':''}`}><span><Mail size={20}/></span><div><strong>{'Globale SendGrid-service'}</strong><p>{data.notificationContext.providerConfigured?'De centrale verzenddienst en afzender van Fieldgrid worden automatisch hergebruikt.':'Het CRM gebruikt de centrale verzenddienst van Fieldgrid. De aanvraag blijft opgeslagen wanneer de centrale maildienst nog configuratie of herstel nodig heeft.'}</p></div></div><div className="crm-email-preview"><div><span>FIELDGRID</span><Mail size={16}/></div><h4>Nieuwe aanvraag via de website</h4><p>Een organisatie wil kennismaken met Fieldgrid.</p><dl><div><dt>Organisatie</dt><dd>Bedrijfsnaam</dd></div><div><dt>Aanvraag</dt><dd>Demo, afspraak of proefperiode</dd></div><div><dt>Volgende stap</dt><dd>Open het dossier en volg op</dd></div></dl><span className="crm-preview-button">Bekijk de aanvraag <ArrowRight size={13}/></span><small>Inhoudsvoorbeeld van de beheerdersmelding</small></div><p className="crm-muted">De melding bevat contactgegevens, de aanvraag en een verwijzing naar het leaddossier.</p></section>
      <div className="crm-settings-footer"><span><ShieldCheck size={15}/>Tijdzone: Europe/Amsterdam</span><Button primary type="submit" disabled={busy}>{busy?'Opslaan…':'Instellingen opslaan'}<Check size={15}/></Button></div>
    </form>
    <section className="crm-mail-log"><div className="crm-tab-heading"><div><h2>Mailregistratie</h2><p>Inzicht in iedere beheerdersmelding en een mogelijkheid om opnieuw te proberen.</p></div><select aria-label="Mailstatus" value={mailFilter} onChange={e=>setMailFilter(e.target.value)}><option value="all">Alle meldingen</option><option value="action">Actie nodig</option><option value="accepted">Aangeboden aan provider</option><option value="pending_config">{mailLabels.pending_config}</option><option value="queued">{mailLabels.queued}</option><option value="sending">{mailLabels.sending}</option><option value="failed">{mailLabels.failed}</option><option value="uncertain">{mailLabels.uncertain}</option><option value="deferred">{mailLabels.deferred}</option><option value="suppressed">{mailLabels.suppressed}</option><option value="cancelled">{mailLabels.cancelled}</option><option value="expired">{mailLabels.expired}</option></select></div>{outbox.length?<Table headers={['Aanvraag','Ontvanger','Status','Moment','Actie']}>{outbox.map(n=>{const l=data.leads.find(l=>l.id===n.leadId);return <tr key={n.id}><td><button className="ed-record" onClick={()=>openLead(n.leadId)}>{l?.company||'Leaddossier'}</button>{n.lastError&&<small className="crm-mail-error">{n.lastError}</small>}</td><td>{n.recipient||data.notificationContext.recipientEmail||'Platformbeheerder · accountadres'}</td><td><StatusMail status={n.status}/><small>{n.attempts} poging{n.attempts===1?'':'en'}</small></td><td>{stamp(n.createdAt)}</td><td><div className="ed-row-actions"><IButton label={`Bekijk melding voor ${l?.company||'lead'}`} onClick={()=>setNotificationId(n.id)}><Mail size={15}/></IButton>{!n.isDemo&&n.status==='failed'?<Button disabled={busy||!data.mailConfigured||!data.settings.emailEnabled} onClick={()=>mutate('/notifications/'+n.id+'/retry','POST',{},'Verzendpoging uitgevoerd. Bekijk de actuele mailstatus.')}><RefreshCw size={14}/>Opnieuw proberen</Button>:<span className="crm-muted">{n.isDemo?'Geen verzending':'—'}</span>}</div></td></tr>})}</Table>:<Empty title="Nog geen mailmeldingen" text="Iedere websiteaanvraag krijgt een herkenbare registratie met de actuele verzendstatus."/>}<p className="crm-muted">“Aangeboden aan provider” bevestigt acceptatie door de verzenddienst; het is geen bewijs dat de e-mail is bezorgd of gelezen.</p></section>
    {notificationId&&<MailPreview data={data} id={notificationId} onClose={()=>setNotificationId(null)} openLead={id=>{setNotificationId(null);openLead(id)}}/>}
  </>
}

function MailPreview({data,id,onClose,openLead}:{data:CrmState;id:string;onClose:()=>void;openLead:(id:string)=>void}){
  const notification=data.notifications.find(n=>n.id===id);
  if(!notification)return null;
  return <Modal title="Beheerdersmelding" subtitle="CRM / MAILREGISTRATIE" onClose={onClose} footer={<><Button onClick={onClose}>Sluiten</Button><Button primary onClick={()=>openLead(notification.leadId)}>Open leaddossier <ArrowUpRight size={15}/></Button></>}><div className="crm-mail-preview-meta"><div><span>Status</span><StatusMail status={notification.status}/></div><div><span>Ontvanger</span><strong>{notification.recipient||data.notificationContext.recipientEmail||'Platformbeheerder · accountadres'}</strong></div><div><span>Aangemaakt</span><strong>{stamp(notification.createdAt)}</strong></div>{notification.acceptedAt&&<div><span>Provideracceptatie</span><strong>{stamp(notification.acceptedAt)}</strong></div>}</div>{notification.lastError&&<Feedback error={notification.lastError}/>}<div className="crm-concrete-email"><span>{notification.transport?'VASTGELEGDE VERZENDINHOUD':'VASTGELEGDE MELDINGSINHOUD'}</span><h3>{notification.transport?.subject||notification.subject||'Beheerdersmelding'}</h3><p className="crm-prewrap">{notification.transport?.text||notification.body||'De centrale worker heeft de inhoud nog niet vastgelegd.'}</p><small>Aanvraagnummer: {notification.requestId}</small></div>{notification.isDemo&&<p className="crm-muted">Dit is een voorbeeldregistratie. Er wordt geen e-mail verstuurd.</p>}</Modal>
}
